CREATE   VIEW [RegsBI].[vwEmail_CE]
AS
SELECT
	[ActivityId],
	[ActivityTypeCode],
	[CreatedOn],
	[CreatedBy],
	[CreatedByName],
	[ModifiedOn],
	[ModifiedBy],
	[ModifiedByName],
	[OwnerId],
	[OwnerIdName],
	[Subject],
	[StateCode],
	[StateCode_Description],
	[StatusCode],
	[StatusCode_Description],
	[OwningUser],
	[OwningTeam],
	[ActualStart],
	[ActualEnd],
	[ActualDurationMinutes],
	[IsBilled],
	[IsBilled_Description],
	[Description],
	[ScheduledStart],
	[ScheduledEnd],
	[ScheduledDurationMinutes],
	[PriorityCode],
	[PriorityCode_Description],
	[RegardingObjectId],
	[RegardingObjectTypeCode],
	[IsRegularActivity],
	[IsRegularActivity_Description],
	[TransactionCurrencyId],
	[TransactionCurrencyIdName],
	[ExchangeRate],
	CAST(NULL AS INT) AS [IsMapiPrivate],
	CAST(NULL AS NVARCHAR) AS [IsMapiPrivate_Description],
	CAST(NULL AS INT) AS [DeliveryPriorityCode],
	CAST(NULL AS NVARCHAR) AS [DeliveryPriorityCode_Description]

FROM [CE].[vwEmail]
